insert into public.programs (slug, program_type, name, description, general_audience, is_published, sort_order, data_source, source_url, source_title, source_checked_on, verification)
values ('student-exchange', 'student-exchange', 'Student Exchange Programs', 'Receiving foreign students for short-term visits and semester exchange/study abroad at MUJ, and sending MUJ students for the same to Collaborative Institutes, within the framework of an MoU/Agreement between the institute and MUJ. MUJ has two forms: the Non-Credit Exchange Program (summer schools, internships, short duration courses) and the Credit Exchange Program (credit-based).', 'Outgoing MUJ students and incoming students of Collaborative Institutes. Non-credit exchanges run from 1 week to 6 months and are encouraged during semester breaks.', true, 0, 'official', 'https://jaipur.manipal.edu/exchange-programs.php', 'Student Exchange — Inbound and Outbound process flow', '2026-09-30', 'source-imported')
on conflict (program_type) do update set
  slug = excluded.slug,
  name = excluded.name,
  description = excluded.description,
  general_audience = excluded.general_audience,
  is_published = excluded.is_published,
  sort_order = excluded.sort_order,
  data_source = excluded.data_source,
  source_url = excluded.source_url,
  source_title = excluded.source_title,
  source_checked_on = excluded.source_checked_on,
  verification = excluded.verification;

insert into public.programs (slug, program_type, name, description, general_audience, is_published, sort_order, data_source, source_url, source_title, source_checked_on, verification)
values ('semester-exchange', 'semester-exchange', 'Semester Exchange (Credit Exchange Program)', 'Courses credited at universities or institutions with which MUJ has an MoU for this purpose may count towards the credit requirement of the MUJ degree, under the Student Exchange Policy. Transferred credit is not used for GPA/CGPA computation; courses must be at the same level or above and approved by the Board of Studies before the student leaves.', 'As stated in the policy: B.Tech students with consistent academic performance and CGPA > 7 (3rd/4th year and semester breaks); non-B.Tech students with CGPA > 7 (2nd/3rd year and semester breaks). Final decisions rest with the Dean of the Faculty.', true, 1, 'official', 'https://jaipur.manipal.edu/img/pdf/Student-Exchange-Policy.pdf', 'Student Exchange Policy (Semester Exchange)', '2026-09-30', 'source-imported')
on conflict (program_type) do update set
  slug = excluded.slug,
