insert into public.programs (slug, program_type, name, description, general_audience, is_published, sort_order, data_source, source_url, source_title, source_checked_on, verification)
values ('pathway-programs', 'pathway-programs', 'Pathway/ Progression', 'Approved pathway models listed by DoIC: 5 years (3 + 1 + 1) with Iowa State University (USA), CESI (France) and The University of Queensland (Australia); 5.5 years (3 + 1 + 1.5) with UMKC (USA).', null, true, 2, 'official', 'https://jaipur.manipal.edu/pathway-progression.php', 'Pathway & Research — Pathway/ Progression', '2026-09-30', 'source-imported')
