insert into public.programs (slug, program_type, name, description, general_audience, is_published, sort_order, data_source, source_url, source_title, source_checked_on, verification)
values ('academic-visits', 'academic-visits', 'Academic and Delegation Visits (Faculty Exchange)', 'DoIC collaborates with international partners so that faculty members can present their work internationally through joint initiatives, research and teaching, and supports brief exchange stays for visiting faculty at MUJ. Academic and delegation visits are recorded on the Faculty Exchange pages.', 'Faculty members of MUJ and visiting faculty from partner institutions.', true, 3, 'official', 'https://jaipur.manipal.edu/international-exchange-opportunities.php', 'Faculty Exchange — International Exchange Opportunities', '2026-09-30', 'source-imported')
